This Terraform configuration creates an AWS DynamoDB table and configures a custom Time to Live, or TTL, attribute for automatic item expiration. The TTL attribute is named `expires_at` by default, but it can be customized using a Terraform variable. DynamoDB expects the TTL attribute value to be a Unix epoch timestamp in seconds.

```hcl
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region where the DynamoDB table will be created."
  type        = string
  default     = "us-east-1"
}

variable "table_name" {
  description = "Name of the DynamoDB table."
  type        = string
  default     = "custom-ttl-demo-table"
}

